<script lang="ts">
	import { goto } from "$app/navigation";
	import { PUBLIC_COVER_URL } from "$env/static/public";
	import { Constants, ExternalLink, Mutex, Permission, Utils } from "$lib";
	import API from "$lib/API";
	import { HTTPError } from "$lib/HTTP";
	import { createMutationOwner, authenticatedMutation, type MutationIntent } from "$platform/authenticated-mutation";
	import { createEditorCoverReader, savedCoverDraft, mergeCurrentCoverDrafts } from "$platform/editor-cover-read";
	import { requireMutationAcknowledgement, reportCurrentMutationFailure } from "$platform/mutation-feedback";
	import type { UpdateCoverRequest } from "$lib/API/Cover";
	import type { UpdateMangaRequest } from "$lib/API/Manga";
	import ConfirmDialog from "$lib/components/ConfirmDialog.svelte";
	import CoversSection from "$lib/components/draft/manga/CoversSection.svelte";
	import LinksSection from "$lib/components/draft/manga/LinksSection.svelte";
	import MetadataSection from "$lib/components/draft/manga/MetadataSection.svelte";
	import RelationsSection from "$lib/components/draft/manga/RelationsSection.svelte";
	import TitleSection from "$lib/components/draft/manga/TitleSection.svelte";
	import { Button } from "$lib/components/ui/button";
	import * as Empty from "$lib/components/ui/empty";
	import { Label } from "$lib/components/ui/label";
	import { Separator } from "$lib/components/ui/separator";
	import { Spinner } from "$lib/components/ui/spinner";
	import * as Tabs from "$lib/components/ui/tabs/index.js";
	import { populateTagList } from "$lib/stores";
	import { CheckIcon, Link, LockIcon, LockOpen, SendIcon, TrashIcon, XIcon } from "@lucide/svelte";
	import equal from "fast-deep-equal";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount } from "svelte";
	import { toast } from "svelte-sonner";
	import Guidelines from "./Guidelines.svelte";
	import TagsSection from "./TagsSection.svelte";

	const { data }: { data: { manga: Manga; covers: Cover[] } } = $props();
	const { pathname } = window.location;
	const mutex = new Mutex();
	const coverMutationOwner = createMutationOwner(() => data.manga.id + "|" + window.location.pathname);
	const editorCoverReader = createEditorCoverReader(() => data.manga.id);
	let unknownCoverIds = $state<string[]>([]), unknownRelationIds = $state<string[]>([]), coverReconciliationRequired = $state(false);
	const STATE = {
		Idle: 0,
		UpdatingEntry: 1,
		UploadingCovers: 2,
		UpdatingCovers: 3,
		DeletingCovers: 4,
		CreatingRelations: 5,
		UpdatingRelations: 6,
		DeletingRelations: 7
	} as const;
	let mutexState = $state<(typeof STATE)[keyof typeof STATE]>(STATE.Idle);

	// svelte-ignore state_referenced_locally
	let manga = $state<Manga>(data.manga);
	// svelte-ignore state_referenced_locally
	let covers = $state<CoverDraft[]>(
		data.covers.map(cover => ({
			...cover,
			valid: true,

			main: cover.id === data.manga.relationships.cover?.id,
			url: `${PUBLIC_COVER_URL}/${data.manga.id}/${cover.id}${cover.ext}`,
			thumbnail: `${PUBLIC_COVER_URL}/${data.manga.id}/${cover.id}.512.webp`
		}))
	);

	const initial = $derived.by<MangaDraft>(() => {
		const snapshot = $state.snapshot(manga);
		return {
			title: snapshot.title,
			description: snapshot.description,
			year: snapshot.year ?? null!,
			language: snapshot.language,
			demographic: snapshot.demographic ?? null!,
			status: snapshot.status,
			content_rating: snapshot.content_rating,

			last_volume: snapshot.last_volume ?? null!,
			last_chapter: snapshot.last_chapter ?? null!,

			covers: covers ? structuredClone($state.snapshot(covers)) : [],
			relations: snapshot.relationships.relations ? structuredClone(snapshot.relationships.relations) : [],

			alt_titles: Object.entries(snapshot.alt_titles ?? [])
				.map(([language, titles]) => titles.map(title => ({ language, title, valid: true })))
				.flat(),
			tags: snapshot.relationships.tags?.map(e => e.id).sort((a, b) => a.localeCompare(b)) ?? [],
			authors: <Author[]>(<any>(snapshot.relationships.authors?.sort((a, b) => a.name.localeCompare(b.name)) ?? [])),
			artists: <Author[]>(<any>(snapshot.relationships.artists?.sort((a, b) => a.name.localeCompare(b.name)) ?? [])),
			links: Object.entries(snapshot.relationships.links ?? []).map(([code, link]) => ({
				code,
				link: ExternalLink.build(code, link),
				valid: true
			}))
		};
	});
	// svelte-ignore state_referenced_locally
	let draft = $state<MangaDraft>(structuredClone($state.snapshot(initial)));

	const isCompletedOrCancelled = $derived(
		[Constants.Manga.PublicationStatus.Completed, Constants.Manga.PublicationStatus.Cancelled].includes(draft.status)
	);
	const isVolumeValid = $derived(
		isCompletedOrCancelled && draft.last_volume ? Utils.isValidVolumeChapter(draft.last_volume) : true
	);
	const isChapterValid = $derived(
		isCompletedOrCancelled && draft.last_chapter ? Utils.isValidVolumeChapter(draft.last_chapter) : true
	);

	const isChanged = $derived(
		!equal(initial, {
			...draft,
			alt_titles: draft.alt_titles.filter(title => title.language && title.title),
			links: draft.links.filter(link => link.code && link.link)
		})
	);
	const isValid = $derived(
		draft?.title &&
			isVolumeValid &&
			isChapterValid &&
			draft.authors.length &&
			draft.artists.length &&
			!coverReconciliationRequired && !unknownRelationIds.length && draft.covers.every(e => e.valid && !unknownCoverIds.includes(e.id!)) &&
			draft.alt_titles.every(e => e.valid) &&
			draft.links.every(e => e.valid)
	);

	onMount(async () => {
		try {
			await populateTagList();
		} catch (e) {
			console.error(e);
		}
	});

	onDestroy(() => {
		draft.covers.forEach(cover => {
			if (cover.thumbnail && cover.thumbnail.startsWith("blob:")) {
				URL.revokeObjectURL(cover.thumbnail);
			}
		});
	});

	const onSubmit = (ev?: SubmitEvent) => {
		ev?.preventDefault(); ev?.stopPropagation(); ev?.stopImmediatePropagation();
		if (mutex.isLocked() || !manga || !initial || !draft || !isChanged || !isValid) return;
		let intent: MutationIntent;
		try { intent = coverMutationOwner.capture(); }
		catch (cause) { reportCurrentMutationFailure("Title update not admitted", cause, () => true); return; }
		return mutex.exec(async () => {
			try {
				intent.assert(); await updateManga(); intent.assert();
				await processCovers(intent); intent.assert();
				await processRelations(intent); intent.assert();
				onReset(); toast.success("Title updated successfully");
			} catch (cause) {
				reportCurrentMutationFailure("Title update not completed", cause, intent.alive);
			} finally { mutexState = STATE.Idle; }
		}).finally(() => intent.release());
	};

	const onReset = (ev?: Event & { currentTarget: HTMLFormElement }) => {
		ev?.preventDefault(); ev?.stopPropagation(); ev?.stopImmediatePropagation();
		if (coverReconciliationRequired) {
			toast.error("Current covers need confirmation", { description: "A cover operation may have succeeded but its current saved state could not be read. Reload this editor before another change; no upload was replayed." });
			return;
		}
		for (const cover of draft.covers) if (cover.file && cover.thumbnail?.startsWith("blob:")) URL.revokeObjectURL(cover.thumbnail);
		draft = structuredClone($state.snapshot(initial)); unknownCoverIds = []; unknownRelationIds = [];
	};

	const updateManga = async () => {
		if (!manga || !draft) {
			return;
		}

		const payload: UpdateMangaRequest = { version: manga.version };
		Object.entries(draft).forEach(([key, value]) => {
			if (!equal(value, initial[key as keyof MangaDraft])) {
				switch (key) {
					case "year":
						payload.year = value || 0;
						break;
					case "demographic":
						payload.demographic = value || Constants.Manga.Demographic.None;
						break;

					case "alt_titles":
						payload.alt_titles = {};
						(value as { language: string; title: string }[]).forEach(({ language, title }) => {
							(payload.alt_titles![language] ??= []).push(title);
						});
						break;

					case "covers":
					case "relations":
						break;

					case "authors":
					case "artists":
						(payload[key as keyof UpdateMangaRequest] as string[]) = (value as Tag[]).map(({ id }) => id);
						break;

					case "links":
						payload.links = (value as ExternalLink[]).reduce(
							(acc, { code, link }) => {
								link = ExternalLink.validate(code, link);
								if (link) {
									acc[code] = link;
								}
								return acc;
							},
							{} as Record<string, string>
						);
						break;

					default:
						(payload[key as keyof UpdateMangaRequest] as any) = value;
				}
			}
		});
		if (Object.keys(payload).length <= 1) {
			return;
		}

		mutexState = STATE.UpdatingEntry;
		const res = await API.Manga.Update(manga.id, payload);
		if (window.location.pathname !== pathname) {
			return;
		}

		if (res?.status === StatusCodes.OK && res.body) {
			manga = res.body;
		} else if (res?.status === StatusCodes.FORBIDDEN) {
			throw Constants.Error.Forbidden;
		} else if (res?.status === StatusCodes.CONFLICT) {
			throw Constants.Error.UpdateConflict;
		} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
			throw Constants.Error.TooManyRequests;
		} else throw Constants.Error.Unknown;
	};

	const processCovers = async (intent: MutationIntent) => {
		intent.assert();
		const accepted = (row: CoverDraft, body: Cover) => {
			intent.assert();
			if (!body.id || !Number.isInteger(body.version) || body.version <= 0) throw new HTTPError(502, "No real cover ID/version was acknowledged. Read the current covers before trying again.", "Cover outcome unknown");
			const oldThumbnail = row.thumbnail;
			const saved = savedCoverDraft(manga, body, !!row.main);
			if (saved.main) covers = covers.map(other => ({ ...other, main: false }));
			const position = covers.findIndex(other => other.id === body.id);
			covers = position < 0 ? [...covers, saved] : covers.map((other, index) => index === position ? saved : other);
			// Commit the actual identity/version immediately, before the next request.
			Object.assign(row, saved, { file: undefined, deleted: undefined });
			if (oldThumbnail?.startsWith("blob:")) URL.revokeObjectURL(oldThumbnail);
		};
		try {
			for (const row of [...draft.covers]) {
				intent.assert();
				if (row.file) {
					if (unknownCoverIds.includes(row.id!)) throw new HTTPError(409, "This upload has an unknown outcome. Inspect the current saved covers, then use Revert to discard its pending File. It was not replayed.", "Cover outcome unknown");
					const form = new FormData(); form.append("file", row.file); form.append("language", row.language!);
					if (row.volume) form.append("volume", row.volume);
					if (row.description) form.append("description", row.description);
					if (row.main) form.append("main", "true");
					mutexState = STATE.UploadingCovers;
					let knownRejection = false;
					try {
						const result = await authenticatedMutation<Cover>(`/cover/${encodeURIComponent(manga.id)}`, "POST", form, intent);
						knownRejection = !!result && result.status >= 400 && result.status < 500;
						requireMutationAcknowledgement(result, 200, true); accepted(row, result!.body!);
					} catch (cause) {
						if (!knownRejection && intent.alive()) { unknownCoverIds = [...unknownCoverIds, row.id!]; coverReconciliationRequired = true; }
						throw cause;
					}
				} else if (row.deleted) {
					mutexState = STATE.DeletingCovers;
					const result = await authenticatedMutation(`/cover/${encodeURIComponent(row.id!)}`, "DELETE", undefined, intent);
					requireMutationAcknowledgement(result, 204); intent.assert();
					covers = covers.filter(other => other.id !== row.id); draft.covers = draft.covers.filter(other => other.id !== row.id);
				} else {
					const before = covers.find(other => other.id === row.id);
					if (!before) throw new HTTPError(409, "This cover has no current saved identity. Reload the editor before updating it.");
					const payload: UpdateCoverRequest = { version: row.version };
					if (row.volume !== before.volume) payload.volume = row.volume;
					if (row.description !== before.description) payload.description = row.description;
					if (row.language !== before.language) payload.language = row.language;
					if (row.main && row.main !== before.main) payload.main = true;
					if (Object.keys(payload).length === 1) continue;
					mutexState = STATE.UpdatingCovers;
					const result = await authenticatedMutation<Cover>(`/cover/${encodeURIComponent(row.id!)}`, "PUT", payload, intent);
					requireMutationAcknowledgement(result, 200, true); accepted(row, result!.body!);
				}
			}
		} catch (cause) {
			if (!intent.alive()) throw cause;
			coverReconciliationRequired = true;
			try {
				const previous = $state.snapshot(covers), edited = $state.snapshot(draft.covers);
				const currentManga = await editorCoverReader.manga(manga, intent);
				const current = await editorCoverReader.covers(currentManga, intent); intent.assert();
				const fresh = current.map(cover => savedCoverDraft(currentManga, cover));
				// Never reset unrelated metadata or associate unknown Files by filename.
				covers = fresh; draft.covers = mergeCurrentCoverDrafts(previous, edited, fresh);
				if ((currentManga as Manga & { can_mutate?: boolean }).can_mutate === false) window.dispatchEvent(new CustomEvent("weebdex-title-publication-changed", { detail: { id: currentManga.id } }));
				coverReconciliationRequired = false;
			} catch {
				coverReconciliationRequired = true;
				if (intent.alive()) throw new HTTPError(0, "The cover batch stopped and the current saved covers could not be confirmed. Acknowledged real IDs/versions and pending edits were retained. Reload the editor to reconcile before retrying; no upload was replayed.", "Cover reconciliation unavailable");
			}
			if (unknownCoverIds.length) throw new HTTPError(0, "A cover upload may have succeeded without its acknowledgement. Current saved covers were read; pending Files were not matched by name or replayed. Inspect the saved covers, then use Revert to discard unknown pending Files before a new deliberate upload.", "Cover outcome unknown");
			throw cause;
		}
	};

	const processRelations = async (intent: MutationIntent) => {
		intent.assert();
		const applyVersion = (value: unknown) => {
			const version = typeof value === "string" && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
			if (!Number.isSafeInteger(version) || Number(version) <= 0) throw new HTTPError(502, "The actual owning title version was not acknowledged. Read current state before another relation mutation.", "Relation outcome unknown");
			manga.version = Number(version);
		};
		try {
			for (const row of [...draft.relations]) {
				intent.assert(); if (row.id === manga.id) continue;
				const before = manga.relationships.relations?.find(relation => relation.id === row.id);
				if (unknownRelationIds.includes(row.id)) throw new HTTPError(409, "This relation has an unknown outcome. Inspect current saved state and use Revert before a new deliberate change.");
				if (row.deleted && !before) { draft.relations = draft.relations.filter(other => other.id !== row.id); continue; }
				if (!row.deleted && before?.type === row.type) continue;
				let knownRejection = false;
				try {
					if (row.deleted) {
						mutexState = STATE.DeletingRelations;
						const result = await authenticatedMutation(`/manga/${encodeURIComponent(manga.id)}/relations`, "DELETE", { related_id: row.id, version: manga.version }, intent);
						knownRejection = !!result && result.status >= 400 && result.status < 500;
						requireMutationAcknowledgement(result, 204); intent.assert();
						// Removal acknowledgement is durable locally even if its version header is lost.
						manga.relationships.relations = (manga.relationships.relations ?? []).filter(other => other.id !== row.id);
						draft.relations = draft.relations.filter(other => other.id !== row.id);
						applyVersion(result!.headers?.["x-weebdex-manga-version"]);
					} else {
						const method = before ? "PUT" : "POST";
						mutexState = before ? STATE.UpdatingRelations : STATE.CreatingRelations;
						const result = await authenticatedMutation<Relation & { manga_version: number }>(`/manga/${encodeURIComponent(manga.id)}/relations`, method, { related_id: row.id, type: row.type, version: manga.version }, intent);
						knownRejection = !!result && result.status >= 400 && result.status < 500;
						requireMutationAcknowledgement(result, before ? 200 : 201, true); intent.assert();
						if (result!.body!.id !== row.id || result!.body!.type !== row.type) throw new HTTPError(502, "No matching saved relation was acknowledged.");
						const saved = result!.body!;
						manga.relationships.relations = [...(manga.relationships.relations ?? []).filter(other => other.id !== row.id), saved];
						Object.assign(row, saved, { new: false, deleted: undefined });
						applyVersion(saved.manga_version); // never Relation.version or a guessed increment
					}
				} catch (cause) { if (!knownRejection && intent.alive()) unknownRelationIds = [...unknownRelationIds, row.id]; throw cause; }
			}
		} catch (cause) {
			if (!intent.alive()) throw cause;
			coverReconciliationRequired = true;
			try {
				const previous = $state.snapshot(initial), edited = $state.snapshot(draft), oldCovers = $state.snapshot(covers);
				const current = await editorCoverReader.manga(manga, intent);
				const images = await editorCoverReader.covers(current, intent); intent.assert();
				const freshCovers = images.map(cover => savedCoverDraft(current, cover));
				covers = freshCovers; manga = current;
				const next = $state.snapshot(initial);
				// Adopt fresh acknowledged fields only where no local edit was pending.
				for (const key of Object.keys(next) as (keyof MangaDraft)[]) {
					if (key !== "covers" && key !== "relations" && equal(edited[key], previous[key])) (draft as any)[key] = structuredClone(next[key]);
				}
				draft.covers = mergeCurrentCoverDrafts(oldCovers, edited.covers, freshCovers);
				const saved = new Map((current.relationships.relations ?? []).map(relation => [relation.id, relation]));
				draft.relations = edited.relations.flatMap(row => {
					const fresh = saved.get(row.id), before = previous.relations.find(relation => relation.id === row.id);
					saved.delete(row.id);
					if (row.deleted && !fresh) { unknownRelationIds = unknownRelationIds.filter(id => id !== row.id); return []; }
					if (!fresh) return row.new ? [row] : [];
					if (!row.deleted && fresh.type === row.type) unknownRelationIds = unknownRelationIds.filter(id => id !== row.id);
					return [{ ...fresh, type: before?.type !== row.type ? row.type : fresh.type, new: false, deleted: row.deleted }];
				});
				draft.relations = [...draft.relations, ...saved.values()]; coverReconciliationRequired = false;
				if ((current as Manga & { can_mutate?: boolean }).can_mutate === false) window.dispatchEvent(new CustomEvent("weebdex-title-publication-changed", { detail: { id: current.id } }));
			} catch { if (intent.alive()) throw new HTTPError(0, "Earlier acknowledged relations and pending edits were retained, but current owner state could not be read. Reload this editor before another mutation; no relation was replayed.", "Relation reconciliation unavailable"); }
			if (unknownRelationIds.length) throw new HTTPError(0, "A relation change has an unresolved outcome. Current saved state was read; inspect it and use Revert to discard the unresolved local intent before a new deliberate change. No mutation was replayed.", "Relation outcome unknown");
			throw cause;
		}
	};

	const onCommit = () =>
		mutex.exec(async () => {
			try {
				const res = await API.Manga.Commit(manga.id, manga.version);
				if (res?.status === StatusCodes.OK && res.body) {
					manga = res.body;
					toast.success("Draft submitted successfully");
				} else if (res?.status === StatusCodes.BAD_REQUEST && res?.body?.error) {
					throw new Constants.Error.Error("Failed to submit draft", res.body.error);
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else if (res?.status === StatusCodes.CONFLICT) {
					throw Constants.Error.UpdateConflict;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else {
					console.error(e);
					toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
				}
			}
		});

	let isPublishing = $state(false);
	const onPublish = () =>
		mutex.exec(async () => {
			if (manga.state !== Constants.State.Submitted) {
				return;
			}

			isPublishing = true;
			try {
				const res = await API.Manga.Publish(manga.id, manga.version);
				if (res?.status === StatusCodes.OK && res.body) {
					const receipt = res.body as Manga & { publication_scope?: string; publication_status?: string; protocol_event_id?: string; is_unavailable?: boolean };
					if (receipt.relationships) manga = receipt;
					else Object.assign(manga, { state: receipt.state, version: receipt.version, protocol_event_id: receipt.protocol_event_id, is_unavailable: receipt.is_unavailable });
					if (receipt.publication_status === "accepted_pending_projection") {
						toast.info("Signed title accepted", { description: "The original protocol accepted this title. It is waiting for local catalogue processing; public detail is not available yet.", duration: 15000 });
					} else if (receipt.publication_scope === "instance-local") {
						toast.success("Title published on this instance", { description: "Original-protocol publication is not configured here. Other peers were not notified." });
					} else toast.success("Signed title published", { description: "The actual original-protocol receipt was accepted and locally hosted." });
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else if (res?.status === StatusCodes.CONFLICT) {
					throw Constants.Error.UpdateConflict;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else {
					console.error(e);
					toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
				}
			} finally {
				isPublishing = false;
				window.dispatchEvent(new CustomEvent("weebdex-title-publication-changed", { detail: { id: manga.id } }));
			}
		});

	let isRejecting = $state(false);
	const onReject = () =>
		mutex.exec(async () => {
			if (manga.state !== Constants.State.Submitted) {
				return;
			}

			isRejecting = true;
			try {
				const res = await API.Manga.Reject(manga.id, manga.version);
				if (res?.status === StatusCodes.OK && res.body) {
					manga = res.body;
					toast.success("Draft rejected successfully");
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else if (res?.status === StatusCodes.CONFLICT) {
					throw Constants.Error.UpdateConflict;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else {
					console.error(e);
					toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
				}
			} finally {
				isRejecting = false;
			}
		});

	let isUpdatingLock = $state(false);
	const updateLockState = () =>
		mutex.exec(async () => {
			isUpdatingLock = true;
			try {
				const res = await (manga.locked ? API.Manga.Unlock : API.Manga.Lock)(manga.id);
				if (res?.status === StatusCodes.OK && res.body) {
					manga = res.body;
					toast.success("Lock state updated successfully");
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else if (res?.status === StatusCodes.CONFLICT) {
					throw Constants.Error.UpdateConflict;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else {
					console.error(e);
					toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
				}
			} finally {
				isUpdatingLock = false;
			}
		});

	const onDelete = () =>
		mutex.exec(async () => {
			try {
				const res = await API.Manga.Delete(manga.id);
				if (res?.status === StatusCodes.NO_CONTENT) {
					toast.success("Draft deleted successfully");
					goto("/drafts/title");
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else {
					console.error(e);
					toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
				}
			}
		});
</script>

{#if mutexState === STATE.Idle}
	{@const canSubmit =
		[Constants.State.Draft, Constants.State.Rejected].includes(manga.state) && Permission.Manga.canUpdate(manga)}
	{@const canUpdateState = manga.state === Constants.State.Submitted && Permission.Manga.canUpdateState()}
	{@const canUpdateLock = Permission.Manga.canUpdateLock()}

	<form class="flex flex-auto flex-col space-y-5" onsubmit={onSubmit} onreset={onReset}>
		<div class="flex flex-wrap items-center justify-between gap-4">
			<div class="flex flex-wrap items-center gap-x-4 gap-y-2">
				<div class="space-y-1">
					<Label>Created At</Label>
					<time datetime={manga.created_at}>
						{new Date(manga.created_at).toLocaleString("en-US", { dateStyle: "short", timeStyle: "short" })}
					</time>
				</div>
				<div class="space-y-1">
					<Label>Last Updated At</Label>
					<div>
						<time datetime={manga.updated_at}>
							{new Date(manga.updated_at).toLocaleString("en-US", { dateStyle: "short", timeStyle: "short" })}
						</time>
						<span>(Version {manga.version})</span>
					</div>
				</div>
				<div class="space-y-1">
					<Label>Status</Label>
					<div>
						<span
							class:text-slate-400={manga.state === Constants.State.Draft}
							class:text-orange-400={manga.state === Constants.State.Submitted}
							class:text-red-400={manga.state === Constants.State.Rejected}
							class:text-green-400={manga.state === Constants.State.Published}
						>
							{Constants.StateText[manga.state]}
						</span>
					</div>
				</div>
				{#if manga.relationships.submitter && manga.relationships.submitter.name !== "system"}
					<div class="space-y-1">
						<Label>Submitted By</Label>
						<a
							class="hover:text-accent-foreground flex items-center gap-1"
							href="/user/{manga.relationships.submitter.id}"
						>
							<Link class="size-3.5 shrink-0" />
							{manga.relationships.submitter.name}
						</a>
					</div>
				{/if}
			</div>
			{#if canSubmit || canUpdateState || canUpdateLock}
				<div class="flex items-center gap-1">
					{#if canSubmit}
						<ConfirmDialog
							title="Submit Draft"
							description="Are you sure you want to submit this draft?"
							confirmText="Submit"
							variant="default"
							onConfirm={e => e.exec(onCommit)}
							disabled={$mutex}
						>
							{#snippet child({ props })}
								<Button class="w-24" type="button" size="sm" {...props}>
									<SendIcon />
									Submit
								</Button>
							{/snippet}
						</ConfirmDialog>
					{/if}
					{#if canUpdateState}
						<ConfirmDialog
							title="Reject Draft"
							description="Are you sure you want to reject this draft?"
							confirmText="Reject"
							variant="destructive"
							onConfirm={async e => e.exec(onReject)}
							disabled={$mutex}
						>
							{#snippet child({ props })}
								<Button class="w-24 border-none !text-red-400" variant="outline" type="button" size="sm" {...props}>
									{#if $mutex && isRejecting}
										<Spinner />
									{:else}
										<XIcon />
										Reject
									{/if}
								</Button>
							{/snippet}
						</ConfirmDialog>
						<ConfirmDialog
							title="Publish Draft"
							description="Are you sure you want to publish this draft?"
							confirmText="Publish"
							variant="default"
							onConfirm={async e => e.exec(onPublish)}
							disabled={$mutex}
						>
							{#snippet child({ props })}
								<Button class="w-24 border-none !text-green-400" variant="outline" type="button" size="sm" {...props}>
									{#if $mutex && isPublishing}
										<Spinner />
									{:else}
										<CheckIcon />
										Publish
									{/if}
								</Button>
							{/snippet}
						</ConfirmDialog>
					{/if}
					{#if canUpdateLock}
						<ConfirmDialog
							title="{manga.locked ? 'Unlock' : 'Lock'} {manga.state === Constants.State.Published ? 'Title' : 'Draft'}"
							description="Are you sure you want to {manga.locked ? 'unlock' : 'lock'} this {manga.state ===
							Constants.State.Published
								? 'title'
								: 'draft'}?"
							confirmText={manga.locked ? "Unlock" : "Lock"}
							variant={manga.locked ? "default" : "destructive"}
							onConfirm={async e => e.exec(updateLockState)}
							disabled={$mutex}
						>
							{#snippet child({ props })}
								<Button class="w-24 border-none" type="button" variant="outline" size="sm" {...props}>
									{#if $mutex && isUpdatingLock}
										<Spinner />
									{:else if manga.locked}
										<LockOpen />
										Unlock
									{:else}
										<LockIcon />
										Lock
									{/if}
								</Button>
							{/snippet}
						</ConfirmDialog>
					{/if}
				</div>
			{/if}
		</div>
		<Separator />

		<Tabs.Root class="flex-auto space-y-5" value="title">
			<Tabs.List>
				<Tabs.Trigger value="title">Title</Tabs.Trigger>
				<Tabs.Trigger value="metadata">Metadata</Tabs.Trigger>
				<Tabs.Trigger value="tags">Tags</Tabs.Trigger>
				<Tabs.Trigger value="links">Links</Tabs.Trigger>
				<Tabs.Trigger value="relations">Relations</Tabs.Trigger>
				<Tabs.Trigger value="covers">Covers</Tabs.Trigger>
			</Tabs.List>
			<Tabs.Content class="space-y-5" value="title">
				<TitleSection bind:draft disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="metadata">
				<MetadataSection bind:draft {isCompletedOrCancelled} {isVolumeValid} {isChapterValid} disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="tags">
				<TagsSection bind:draft enabled={Permission.Manga.canEditTags(manga)} disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="links">
				<LinksSection bind:draft enabled={Permission.Manga.canEditLinks(manga)} disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="relations">
				<RelationsSection bind:draft enabled={Permission.Manga.canEditRelations(manga)} disabled={$mutex} />
			</Tabs.Content>
			<Tabs.Content class="space-y-5" value="covers">
				<CoversSection bind:draft enabled={Permission.Manga.canEditCovers(manga)} disabled={$mutex} />
			</Tabs.Content>
		</Tabs.Root>

		<Separator />
		<div class="bg-background sticky bottom-0 flex flex-wrap items-center justify-between gap-1 py-1">
			<div>
				{#if Permission.Manga.canDelete(manga)}
					<ConfirmDialog
						title={manga.state === Constants.State.Published ? "Delete Title" : "Delete Draft"}
						description={manga.state === Constants.State.Published
							? "Are you sure you want to delete this title?"
							: "Are you sure you want to delete this draft?"}
						confirmText="Delete"
						variant="destructive"
						onConfirm={e => e.exec(onDelete)}
						disabled={$mutex}
					>
						{#snippet child({ props })}
							<Button class="w-24" variant="destructive" {...props}>
								<TrashIcon />
								Delete
							</Button>
						{/snippet}
					</ConfirmDialog>
				{/if}
			</div>
			<div class="flex items-center gap-1">
				<Button
					class="!text-destructive w-24 border-none"
					variant="outline"
					type="reset"
					disabled={$mutex || !isChanged}
				>
					Revert
				</Button>
				<Button class="w-30" type="submit" disabled={$mutex || !isChanged || !isValid}>Save</Button>
			</div>
		</div>
		<Separator />

		<div class="space-y-2">
			<strong class="block text-xl font-semibold">Guidelines</strong>
			<Guidelines />
		</div>
	</form>
{:else}
	<Empty.Root>
		<Empty.Header>
			<Empty.Media>
				<Spinner class="size-10" />
			</Empty.Media>
			<Empty.Title>
				{#if mutexState === STATE.UpdatingEntry}
					Updating Draft
				{:else if mutexState === STATE.UploadingCovers}
					Uploading Covers
				{:else if mutexState === STATE.UpdatingCovers}
					Updating Covers
				{:else if mutexState === STATE.DeletingCovers}
					Deleting Covers
				{:else if mutexState === STATE.CreatingRelations}
					Creating Relations
				{:else if mutexState === STATE.UpdatingRelations}
					Updating Relations
				{:else if mutexState === STATE.DeletingRelations}
					Deleting Relations
				{/if}
			</Empty.Title>
		</Empty.Header>
	</Empty.Root>
{/if}
